import XCTest

/// The import notice in the editor's band: a document whose pages carry
/// annotations or filled form fields opens with it. Two bundled synthetic
/// documents reach it: `--annotatedDoc` (UITestFixtures/uitest_annotated.pdf,
/// generated by Scripts/generate_uitest_annotated.py), one page with a
/// single note and nothing else, and `--annotatedFormDoc`
/// (UITestFixtures/uitest_annotated_form.pdf), one page with an opaque box
/// annotation and a filled text field. The note alone is what raises the
/// notice on the first; the close and the band's place are read on the
/// second. Every step runs inside the notice's reading time, so a notice
/// that meets the page cannot pass by folding; the one exception is Search's
/// close, where the notice or its mark counts (its test says why).
///
/// nonisolated for the same reason as the sibling suites: an XCUITest
/// drives a separate process and touches no @MainActor app state.
nonisolated final class ImportNoticeUITests: XCTestCase {

    private var app: XCUIApplication!

    override func setUp() {
        super.setUp()
        continueAfterFailure = false
        app = XCUIApplication()
    }

    override func tearDown() {
        app = nil
        super.tearDown()
    }

    private func element(_ identifier: String) -> XCUIElement {
        app.descendants(matching: .any).matching(identifier: identifier).firstMatch
    }

    private var notice: XCUIElement { element("importAnnotationNotice") }
    private var mark: XCUIElement { element("noticeFoldedMark") }

    private func launch(_ arguments: [String]) {
        app.launchArguments = ["--uitesting", "--loadTestDocument"] + arguments
        app.launch()
    }

    /// A document whose only annotation is a note opens with the import notice.
    func testADocumentWithANoteOpensWithTheImportNotice() {
        launch(["--annotatedDoc"])
        XCTAssertTrue(notice.waitForExistence(timeout: 30),
                      "A document with one note did not open with the import notice.")
        attachScreenshot(named: "import-notice-note")
    }

    /// The import notice sits under the toolbar, and Dismiss closes it.
    func testTheImportNoticeSitsUnderTheToolbarAndDismissClosesIt() {
        launch(["--annotatedFormDoc"])
        XCTAssertTrue(notice.waitForExistence(timeout: 30), "The import notice did not come up.")
        let gap = notice.frame.minY - app.navigationBars.firstMatch.frame.maxY
        XCTAssertEqual(gap, 8, accuracy: 2, "The notice is \(gap) pt under the toolbar.")
        let close = notice.buttons["noticeClose"].firstMatch
        XCTAssertTrue(close.exists, "The notice has no Dismiss.")
        attachScreenshot(named: "import-notice-open")
        // 20 above the glyph's centre: outside its drawing, inside its 46.
        close.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5)).withOffset(CGVector(dx: 0, dy: -20)).tap()
        XCTAssertTrue(notice.waitForNonExistence(timeout: 5), "A tap 20 above the close's glyph did not close the notice.")
        XCTAssertFalse(mark.exists, "The notice folded to its mark instead of closing.")
    }

    /// Search at half height hides the band, and closing Search brings it back.
    /// The notice comes back open, and folds to its mark at once when the
    /// page moves under it as Search and the keyboard leave: in a full run
    /// it was open about 0.2 s before the page settled. Either one, the open
    /// notice or its mark, is the band shown again; neither shows under
    /// Search, as the first two asserts hold.
    func testSearchAtHalfHeightHidesTheBandAndClosingSearchBringsItBack() {
        launch(["--annotatedFormDoc", "--openSearchSheet", "--searchDetent=medium"])
        XCTAssertTrue(app.textFields["Search text"].waitForExistence(timeout: 30), "Search did not open.")
        XCTAssertFalse(notice.exists, "The import notice shows under Search at half height.")
        XCTAssertFalse(mark.exists, "The folded mark shows under Search at half height.")
        let dismiss = app.buttons["searchDismissButton"].firstMatch
        XCTAssertTrue(dismiss.waitForExistence(timeout: 10), "Search has no close.")
        dismiss.tap()
        XCTAssertTrue(dismiss.waitForNonExistence(timeout: 10), "Search did not close.")
        let deadline = Date().addingTimeInterval(10)
        var seen: String?
        repeat {
            if notice.exists {
                seen = "open"
            } else if mark.exists {
                seen = "folded mark"
            }
        } while seen == nil && Date() < deadline
        // Named in the log and the result, so each run records how often the
        // notice had already folded.
        XCTContext.runActivity(named: "Import notice back after Search: \(seen ?? "neither")") { _ in }
        XCTAssertNotNil(seen, "Closing Search brought back neither the import notice nor its folded mark.")
    }
}
